#!/bin/bash
# run_fault.sh NAME KEY NODE SIDE(c|p) OBSERVE_SECONDS "FAULT_CMD (run with nohup on NODE; must print '<ms> <EVENT>' first line to /tmp/fault.log)"
cd ~/pgk8s; NAME=$1 KEY=$2 NODE=$3 SIDE=$4 OBS=$5 FAULT=$6
OUT=results/sb_$NAME; mkdir -p $OUT; S="ssh -F ssh_config"
TRUNC="truncate sb2 restart identity"
$S pk-cp "source h.sh; if [ $SIDE = c ]; then psqlc -d app -c \"$TRUNC\"; elif [ $SIDE = k ]; then psqlk -d hippo -c \"$TRUNC\"; else psqlp -d cluster1 -c \"$TRUNC\"; fi; kubectl -n probe delete pod writers-$NAME --ignore-not-found >/dev/null; sed -e s/NAME/$NAME/ -e s/KEY/$KEY/ > /tmp/w.yaml; kubectl apply -f /tmp/w.yaml >/dev/null; kubectl -n probe wait --for=condition=Ready pod/writers-$NAME --timeout=60s >/dev/null" < sb/writers.yaml.tpl
sleep 20
$S $NODE "rm -f /tmp/fault.log; nohup bash -c \"$FAULT\" > /tmp/fault.log 2>&1 &"; sleep 2
TP=$($S $NODE "head -1 /tmp/fault.log" | awk '{print $1}'); echo "fault at $TP: $($S $NODE head -1 /tmp/fault.log)" | tee $OUT/summary.txt
$S pk-cp "source h.sh; T0=$TP; for i in \$(seq 1 $((OBS/10))); do sleep 10; s=\$(( (\$(date +%s%3N)-T0)/1000 )); if [ $SIDE = c ]; then echo \"+\${s}s cur=\$(cprim) target=\$(kubectl get cluster cluster-example -o jsonpath={.status.targetPrimary}) phase=\\\"\$(kubectl get cluster cluster-example -o jsonpath={.status.phase})\\\" pods=\$(kubectl get pods -l cnpg.io/cluster=cluster-example --no-headers | awk '{print \$1\":\"\$2\":\"\$3\":\"\$4}' | tr '\n' ' ')\"; elif [ $SIDE = k ]; then echo \"+\${s}s masters=\$(kubectl -n crunchy get pods -l postgres-operator.crunchydata.com/role=master -o name | cut -d/ -f2 | tr '\n' ,)\"; else echo \"+\${s}s primaries=\$(kubectl -n \$NSP get pods -l postgres-operator.crunchydata.com/role=primary -o name | cut -d/ -f2 | tr '\n' ,) pods=\$(kubectl -n \$NSP get pods --no-headers | grep instance1 | awk '{print \$1\":\"\$2\":\"\$3\":\"\$4}' | tr '\n' ' ')\"; fi; done" > $OUT/status.log
$S $NODE "cat /tmp/fault.log" >> $OUT/summary.txt
$S pk-cp "kubectl -n probe exec writers-$NAME -- bash -c 'pkill -f writer.sh; sleep 1; true'; for i in 1 2 3; do kubectl -n probe exec writers-$NAME -- cat /tmp/c\$i.log > /tmp/sb_c\$i.log; done"; for i in 1 2 3; do scp -qF ssh_config pk-cp:/tmp/sb_c$i.log $OUT/c$i.log; done
$S pk-cp "source h.sh; if [ $SIDE = c ]; then psqlc -d app -c 'select id||chr(124)||client||chr(124)||ts from sb2'; elif [ $SIDE = k ]; then psqlk -d hippo -c 'select id||chr(124)||client||chr(124)||ts from sb2'; else psqlp -d cluster1 -c 'select id||chr(124)||client||chr(124)||ts from sb2'; fi" > $OUT/final.txt
if [ $SIDE = c ]; then $S pk-cp "for p in \$(kubectl get pods -l cnpg.io/cluster=cluster-example -o name); do kubectl logs \$p -c postgres --since=20m 2>/dev/null | grep -E 'ready to accept connections|received promote|shutting down|Primary lease|isolat' | grep -oE '\"ts\":\"[^\"]*|\"(msg|message)\":\"[^\"]{0,80}' | paste -s -d' ' | sed \"s#^#\$p #\" | cut -c1-3000; done" > $OUT/pglog.txt
else $S pk-cp "for p in \$(kubectl -n postgres-operator get pods -o name | grep instance1); do echo \"== \$p\"; kubectl -n postgres-operator logs \$p -c database --since=20m 2>/dev/null | grep -E 'promoted self|demot|DCS|lock|read-only|demoting' | grep -v 'no action' | head -20; done" > $OUT/pglog.txt; fi
python3 sb/analyze_sb.py $OUT $TP | tee -a $OUT/summary.txt
